func main() {
	var (
		name    string
		age     int
		verbose bool
	)

	flag.StringVar(&name, "name", "Инженер", "Имя пользователя")
	flag.IntVar(&age, "age", 25, "Возраст пользователя")
	flag.BoolVar(&verbose, "verbose", false, "Включить подробный вывод")

	flag.Parse()

	if verbose {
		fmt.Println("[DEBUG] Режим подробного логирования включен")
		fmt.Printf("[DEBUG] Количество переданных аргументов: %d\n", flag.NFlag())
	}

	fmt.Printf("Пользователь: %s, Возраст: %d лет\n", name, age)
}

package main

import (
	"flag"
	"fmt"
	"os"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Использование: app <add|sub> [флаги]")
		os.Exit(1)
	}

	// 1. Подкоманда add
	addCmd := flag.NewFlagSet("add", flag.ExitOnError)
	addX := addCmd.Int("x", 0, "Первое слагаемое")
	addY := addCmd.Int("y", 0, "Второе слагаемое")

	// 2. Подкоманда sub
	subCmd := flag.NewFlagSet("sub", flag.ExitOnError)
	subX := subCmd.Int("x", 0, "Уменьшаемое")
	subY := subCmd.Int("y", 0, "Вычитаемое")

	switch os.Args[1] {
	case "add":
		addCmd.Parse(os.Args[2:])
		fmt.Printf("%d + %d = %d\n", *addX, *addY, *addX+*addY)
	case "sub":
		subCmd.Parse(os.Args[2:])
		fmt.Printf("%d - %d = %d\n", *subX, *subY, *subX-*subY)
	default:
		fmt.Printf("Неизвестная команда: %s. Доступны: add, sub\n", os.Args[1])
		os.Exit(1)
	}
}

